17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.HouseholdResolver;
31	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
32	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.Region;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
42	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
43	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
44	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
55	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    private final IdentityKeyResolver identityKeyResolver;
101	
102	    private final HouseholdResolver householdResolver;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 AddressNormalizer addressNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 IdentityKeyResolver identityKeyResolver,
112	                                 HouseholdResolver householdResolver) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.emailNormalizer = emailNormalizer;
120	        this.identityKeyResolver = identityKeyResolver;
121	        this.householdResolver = householdResolver;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        owners.forEach(this::populateHouseholdMemberCount);
137	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
138	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        populateHouseholdMemberCount(owner);
149	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
154	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
155	     * by the mapper alone.
156	     *
157	     * @param owner the owner to map
158	     * @return the owner DTO carrying its identity key
159	     */
160	    private OwnerDto toOwnerDto(Owner owner) {
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
163	        return ownerDto;
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        normalizeAndValidate(ownerFieldsDto);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        populateDerivedFields(owner, ownerFieldsDto);
174	        requireUniqueIdentity(owner);
175	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
176	        flagPossibleDuplicate(owner, ownerFieldsDto);
177	        this.clinicService.saveOwner(owner);
178	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
179	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
180	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
181	        populateHouseholdMemberCount(owner);
182	        OwnerDto ownerDto = toOwnerDto(owner);
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    /**
189	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
190	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
191	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
192	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
193	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
194	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
195	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
196	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
197	     *
198	     * @param owner          the newly mapped owner about to be saved
199	     * @param ownerFieldsDto the incoming owner payload
200	     */
201	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
202	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
203	        owner.setNamesakeCount(countNamesakes(owner));
204	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
205	        assignHouseholdId(owner);
206	    }
207	
208	    /**
209	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
210	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
211	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
212	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
213	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
214	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
215	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
216	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
217	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
218	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
219	     * assigned (see {@link #requireUniqueIdentity}).
220	     *
221	     * @param ownerFieldsDto the incoming owner payload, mutated in place
222	     * @throws MissingOwnerFieldsException if any required field is missing or blank
223	     */
224	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
225	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
226	        validateRequiredFields(ownerFieldsDto);
227	        validatePostcode(ownerFieldsDto);
228	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
229	        ownerFieldsDto.setTelephone(telephone);
230	        requireCityHasCapacity(ownerFieldsDto.getCity());
231	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
232	        ownerFieldsDto.setRegistrationDate(registrationDate);
233	        requireDailyLimitNotReached(registrationDate);
234	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
235	        ownerFieldsDto.setEmail(email);
236	    }
237	
238	    /**
239	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
240	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
241	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
242	     * later than the current server date is rejected.
243	     *
244	     * @param ownerFieldsDto the incoming owner payload
245	     * @return the effective registration date rolled forward onto a business day
246	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
247	     */
248	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
249	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
250	        if (effective == null) {
251	            effective = LocalDate.now();
252	        }
253	        else if (effective.isAfter(LocalDate.now())) {
254	            throw new FutureRegistrationDateException(
255	                "the registration date must not be later than the current server date");
256	        }
257	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
258	            effective = effective.plusDays(1);
259	        }
260	        return effective;
261	    }
262	
263	    /**
264	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
265	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
266	     * further owner may be created for that day.
267	     *
268	     * @param registrationDate the adjusted business-day registration date of the owner being created
269	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
270	     */
271	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
272	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
273	            throw new DailyOwnerLimitExceededException(
274	                "the maximum number of owners for today has already been reached");
275	        }
276	    }
277	
278	    /**
279	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
280	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
281	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
282	     * warning threshold) so both express the same per-day count in one place.
283	     *
284	     * @param registrationDate the adjusted business-day registration date to count owners for
285	     * @return the number of existing owners registered on that day
286	     */
287	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
288	        return this.clinicService.findAllOwners().stream()
289	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
290	            .count();
291	    }
292	
293	    /**
294	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
295	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
296	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
297	     * reflects only owners that predate it.
298	     *
299	     * @param registrationDate the adjusted business-day registration date of the owner being created
300	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
301	     */
302	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
303	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
304	    }
305	
306	    /**
307	     * Counts how many existing owners already share the given owner's first and last name, compared
308	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
309	     * create; it is zero when the owner's name is unique.
310	     *
311	     * @param owner the newly mapped owner about to be saved
312	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
313	     */
314	    private int countNamesakes(Owner owner) {
315	        String firstName = owner.getFirstName();
316	        String lastName = owner.getLastName();
317	        return (int) this.clinicService.findAllOwners().stream()
318	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
319	                && lastName.equalsIgnoreCase(existing.getLastName()))
320	            .count();
321	    }
322	
323	    /**
324	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
325	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
326	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
327	     *
328	     * @param ownerFieldsDto the owner payload to validate
329	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
330	     */
331	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
332	        List<String> missingFields = new ArrayList<>();
333	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
334	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
335	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
336	        requireText(missingFields, "city", ownerFieldsDto.getCity());
337	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
338	        if (!missingFields.isEmpty()) {
339	            throw new MissingOwnerFieldsException(missingFields);
340	        }
341	    }
342	
343	    private void requireText(List<String> missingFields, String fieldName, String value) {
344	        if (value == null || value.isBlank()) {
345	            missingFields.add(fieldName);
346	        }
347	    }
348	
349	    /**
350	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
351	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
352	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
353	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
354	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
355	     *
356	     * @param ownerFieldsDto the incoming owner payload
357	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
358	     */
359	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
360	        String postcode = ownerFieldsDto.getPostcode();
361	        if (postcode == null) {
362	            return;
363	        }
364	        Region region = Region.forCity(ownerFieldsDto.getCity());
365	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
366	            throw new InvalidPostcodeException(
367	                "postcode " + postcode + " is not valid for the city's region " + region.name());
368	        }
369	    }
370	
371	    /**
372	     * Rejects creating an owner whose whole derived {@code identityKey} (see
373	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
374	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
375	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
376	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
377	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
378	     *
379	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
380	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
381	     */
382	    private void requireUniqueIdentity(Owner owner) {
383	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
384	        boolean inUse = this.clinicService.findAllOwners().stream()
385	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
386	        if (inUse) {
387	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
388	        }
389	    }
390	
391	    /**
392	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
393	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
394	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
395	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
396	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
397	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
398	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
399	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
400	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
401	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
402	     *
403	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
404	     * @param ownerFieldsDto the incoming owner payload
405	     */
406	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
407	        owner.setPossibleDuplicate(false);
408	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
409	            return;
410	        }
411	        String postcode = owner.getPostcode();
412	        if (postcode == null || postcode.isBlank()) {
413	            return;
414	        }
415	        String lastName = owner.getLastName();
416	        String telephone = owner.getTelephone();
417	        for (Owner existing : this.clinicService.findAllOwners()) {
418	            if (lastName.equalsIgnoreCase(existing.getLastName())
419	                && postcode.equals(existing.getPostcode())
420	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
421	                owner.setPossibleDuplicate(true);
422	                owner.setPossibleDuplicateOf(existing.getId());
423	                return;
424	            }
425	        }
426	    }
427	
428	    /**
429	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
430	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
431	     *
432	     * @param city the city of the owner being created
433	     * @throws OwnerCityFullException if the city already contains 50 or more owners
434	     */
435	    private void requireCityHasCapacity(String city) {
436	        long cityOwners = this.clinicService.findAllOwners().stream()
437	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
438	            .count();
439	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
440	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
441	        }
442	    }
443	
444	    /**
445	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
446	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
447	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
448	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
449	     * such owners never match one another as a household.
450	     *
451	     * @param owner the newly mapped owner about to be saved
452	     */
453	    private void assignHouseholdId(Owner owner) {
454	        String postcode = owner.getPostcode();
455	        if (postcode == null || postcode.isBlank()) {
456	            owner.setHouseholdId(null);
457	            return;
458	        }
459	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
460	    }
461	
462	    /**
463	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
464	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
465	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
466	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
467	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
468	     * without a postcode) can never be a household duplicate.
469	     *
470	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
471	     * @param ownerFieldsDto the incoming owner payload
472	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
473	     *                                 declare {@code sharesHousehold}
474	     */
475	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
476	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
477	            return;
478	        }
479	        String householdId = owner.getHouseholdId();
480	        if (householdId == null) {
481	            return;
482	        }
483	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
484	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
485	        if (sharedByExisting) {
486	            throw new DuplicateOwnerException("an owner in the same household already exists");
487	        }
488	    }
489	
490	    /**
491	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
492	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
493	     * household is counted as a household of one.
494	     *
495	     * @param owner the owner whose household size should be resolved
496	     */
497	    private void populateHouseholdMemberCount(Owner owner) {
498	        String householdId = owner.getHouseholdId();
499	        if (householdId == null) {
500	            owner.setHouseholdMemberCount(1);
501	            return;
502	        }
503	        long members = this.clinicService.findAllOwners().stream()
504	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
505	            .count();
506	        owner.setHouseholdMemberCount((int) members);
507	    }
508	
509	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
510	    @Override
511	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
512	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
513	        if (currentOwner == null) {
514	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
515	        }
516	        validatePostcode(ownerFieldsDto);
517	        currentOwner.setAddress(ownerFieldsDto.getAddress());
518	        currentOwner.setCity(ownerFieldsDto.getCity());
519	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
520	        currentOwner.setLastName(ownerFieldsDto.getLastName());
521	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
522	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
523	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
524	        this.clinicService.saveOwner(currentOwner);
525	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
526	    }
527	
528	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
529	    @Transactional
530	    @Override
531	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
532	        Owner owner = this.clinicService.findOwnerById(ownerId);
533	        if (owner == null) {
534	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	        }
536	        this.clinicService.deleteOwner(owner);
537	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
538	    }
539	
540	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
541	    @Override
542	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
543	        Owner owner = this.clinicService.findOwnerById(ownerId);
544	        if (owner == null) {
545	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
546	        }
547	        HttpHeaders headers = new HttpHeaders();
548	        Pet pet = petMapper.toPet(petFieldsDto);
549	        owner.setId(ownerId);
550	        pet.setOwner(owner);
551	        pet.getType().setName(null);
552	        this.clinicService.savePet(pet);
553	        PetDto petDto = petMapper.toPetDto(pet);
554	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
555	            .buildAndExpand(pet.getId()).toUri());
556	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
557	    }
558	
559	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
560	    @Override
561	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
562	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
563	        if (currentOwner != null) {
564	            Pet currentPet = this.clinicService.findPetById(petId);
565	            if (currentPet != null) {
566	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
567	                currentPet.setName(petFieldsDto.getName());
568	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
569	                this.clinicService.savePet(currentPet);
570	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
571	            }
572	        }
573	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
574	    }
575	
576	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
577	    @Override
578	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
579	        HttpHeaders headers = new HttpHeaders();
580	        Visit visit = visitMapper.toVisit(visitFieldsDto);
581	        Pet pet = new Pet();
582	        pet.setId(petId);
583	        visit.setPet(pet);
584	        this.clinicService.saveVisit(visit);
585	        VisitDto visitDto = visitMapper.toVisitDto(visit);
586	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
587	            .buildAndExpand(visit.getId()).toUri());
588	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
589	    }
590	
591	
592	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
593	    @Override
594	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
595	        Owner owner = this.clinicService.findOwnerById(ownerId);
596	        if (owner != null) {
597	            Pet pet = owner.getPet(petId);
598	            if (pet != null) {
599	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
600	            }
601	        }
602	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
603	    }
604	}
